import type { Metadata } from "next";
import Image from "next/image";
import Link from "next/link";
import { ContactCta } from "@/components/contact-cta";
import type { FaqItem } from "@/components/landing/landing-faq";
import { INK, SHOP } from "@/components/home/street-kit";
import { buildsFor } from "@/components/web-catalogue/web-catalogue";
import { BOOKING_HREF, BOOKING_NOTE } from "@/lib/booking";
import {
  CARE_CHANGES_LINE,
  CARE_CHANGE_LIMIT,
  CARE_LITE,
  CARE_LITE_AMOUNT,
  EXTRA_HOURLY,
  EXTRA_HOURLY_CLIENT,
  OWNERSHIP_LINE,
  PLAN_INCLUDES,
  PLAN_STOP_CARE,
  SEO_AUDIT,
  SEO_AUDIT_BUY_URL,
  SEO_ONGOING,
  SEO_ONGOING_12MO,
  SEO_ONGOING_6MO,
  SEO_ONGOING_EXTRA_SCOPE,
  VISIBILITY_LINE,
  WEB_ADDONS,
  WEB_FROM,
  WEB_TIERS,
  offerPrice,
} from "@/lib/pricing";
import { OFFER_CATALOG_ID, ORG_ID } from "@/lib/organisation";
import { STARTER_FASHION_BUILDS, TEMPLATE_VERTICALS, lookPortrait } from "@/lib/templates";

/* LAYOUT: "Colour bands", picked by Macdara from the static /pricing workshop
 * on 2026-10-01 (redesign step 5). The /websites idiom applied to prices: a
 * butter band for the two builds, each beside pictures of what it buys (one
 * look per trade for Starter, what Custom includes); an
 * ocean band for AI Search with its three prices as tiles; a light band for
 * what happens after launch. The comparison table and the two notes were cut
 * on his call the same day; their facts now sit in the closed questions.
 *
 * Every figure renders from lib/pricing.ts - the page holds no price of its
 * own, so a reprice lands here without an edit. check:prices and
 * check:surface-prices both cover this file. */

export const metadata: Metadata = {
  title: "Pricing",
  description: `Websites ${WEB_FROM}, the audit at ${SEO_AUDIT}, the ongoing plan at ${SEO_ONGOING}. Fixed numbers, agreed in writing.`,
  alternates: { canonical: "https://solaisoft.com/pricing" },
};

const jsonLd = {
  "@context": "https://schema.org",
  "@type": "OfferCatalog",
  "@id": OFFER_CATALOG_ID,
  name: "Solaisoft pricing",
  // The business node from the home page, not a second anonymous Organization:
  // that is what lets an engine attach these prices to Solaisoft.
  provider: { "@id": ORG_ID },
  // offerPrice() decides between a price, a minPrice and a range (lib/pricing.ts).
  itemListElement: [
    ...WEB_TIERS.map((t) => ({
      "@type": "Offer",
      name: `${t.name} website`,
      priceCurrency: "AUD",
      ...offerPrice(t.price),
    })),
    { "@type": "Offer", name: "SEO and AI-search audit", price: SEO_AUDIT.replace("$", ""), priceCurrency: "AUD" },
    {
      "@type": "Offer",
      name: "Ongoing SEO and AI-search plan",
      price: SEO_ONGOING.replace(/[^0-9.]/g, ""),
      priceCurrency: "AUD",
    },
  ],
};

/* A tier lookup that misses fails the build rather than publishing a card or
 * an answer about a tier that no longer exists. */
function tier(name: string) {
  const t = WEB_TIERS.find((x) => x.name === name);
  if (!t) throw new Error(`/pricing names tier "${name}", which WEB_TIERS no longer has`);
  return t;
}
const lcfirst = (s: string) => s.charAt(0).toLowerCase() + s.slice(1);
const perMonth = (s: string) => s.replace("/mo", " a month");
const STARTER = tier("Starter");
const CUSTOM = tier("Custom");
const firstLooks = TEMPLATE_VERTICALS.map((v) => v.looks[0]);
// One site per trade plus the first fashion build: Starter's picks.
const fashionLead = buildsFor(STARTER_FASHION_BUILDS.slice(0, 1));

/* THE QUESTIONS. The buyer questions from the approved v2 prompt set
 * (docs/aeo/iab50-migration/solaisoft-50-v2-2026-09-27.md: #4, #31, #45, #47,
 * #48, #49 and the free-quote prompt), plus the fine print from the two notes
 * cut on 2026-10-01. All closed: the facts stay on the page and in the
 * FAQPage JSON-LD, and only the questions count as visible words. */
const FAQ: FaqItem[] = [
  {
    q: "How much does a small business website cost?",
    a: `${STARTER.name} is ${STARTER.price}: one page on one of our ready-made sites, with your words and photos. ${CUSTOM.name} is ${CUSTOM.price}: up to 10 pages designed for your brand. Hosting and care is then ${CARE_LITE_AMOUNT} a month. The price is fixed and agreed in writing before we start.`,
  },
  {
    q: "How fast can you build my website?",
    a: `On ${STARTER.name}: ${lcfirst(STARTER.timeline)}. On ${CUSTOM.name}, the timeline is ${lcfirst(CUSTOM.timeline)}.`,
  },
  {
    q: "Is there a lock-in contract?",
    a: `On Starter, no. On Custom, care has a 12-month minimum, then runs month to month. Otherwise, care (${CARE_LITE_AMOUNT} a month) and the search plan (${perMonth(SEO_ONGOING)}) run month to month, and you can cancel either with 30 days' notice. ${OWNERSHIP_LINE}`,
  },
  {
    q: "How much does SEO cost per month?",
    a: `A ${SEO_AUDIT} audit first, then ${perMonth(SEO_ONGOING)}, month to month. The plan includes ${lcfirst(PLAN_INCLUDES)}`,
  },
  {
    q: `What else does the ${SEO_ONGOING} plan cover?`,
    // Conditional on hosting: care carries the changes, and only a site we
    // host has care (A1 cl.6, A3 cl.2). ELI5 buyer pass on #1163, 2026-10-01.
    a: `If we host your site, it also covers ${lcfirst(CARE_CHANGES_LINE)} ${CARE_CHANGE_LIMIT} It covers one location and one service line; each extra one is ${SEO_ONGOING_EXTRA_SCOPE}. Other manual work you ask for beyond the plan: ${EXTRA_HOURLY_CLIENT} an hour (${EXTRA_HOURLY} without care or the plan), billed in 15-minute steps with a 30-minute minimum per job. Bigger jobs are priced and agreed in writing before we start.`,
  },
  {
    q: "Can I prepay, and what happens when I stop?",
    a: `Prepay 6 months for ${SEO_ONGOING_6MO}, or 12 months for ${SEO_ONGOING_12MO}, in one payment, with everything in the plan included the whole way through. If you cancel during a prepaid term, it does not renew: the plan runs to the end of the term, and unused months are not refunded. ${PLAN_STOP_CARE}`,
  },
  {
    q: "Can I get a free quote?",
    a: "Yes. Tell us what you need, and you get a firm quote within one business day. The quote costs nothing and commits you to nothing.",
    more: { href: "#contact", label: "Ask for a quote" },
  },
  {
    q: "Can you check my website for free?",
    a: "Yes. Send us your business, your website and the search you want to win. Within one business day you get a written diagnosis by email: where you rank, what AI assistants say about you, and what to fix first.",
    more: { href: "/diagnosis", label: "Get the free diagnosis" },
  },
];

/* CUSTOM QUESTIONS. Drafted unreviewed on 2026-10-13 at Macdara's request
 * ("write the copy yourself, I will review it afterwards"). Facts come from
 * lib/pricing.ts; the wording awaits his edit. */
const CUSTOM_FAQ: FaqItem[] = [
  {
    q: "What do I get on Custom?",
    a: `${CUSTOM.price}: a site designed around your brand, with up to 10 pages, site search built in at no extra fee, and the search foundation set up before launch. The scope and timeline are agreed in writing with your quote.`,
  },
  {
    q: "Do I need to supply my own photos?",
    a: `Yes. Photography is yours and we design around it. If you want booking or other extras, they are priced separately: ${WEB_ADDONS.map((a) => `${lcfirst(a.name)} ${a.price}`).join(", ")}.`,
  },
  {
    q: "What does Custom cost after launch?",
    a: `Care is ${CARE_LITE_AMOUNT} a month. It covers hosting, security, updates, the site-health portal and ${CARE_CHANGES_SHORT}. Care has a 12-month minimum from the first payment, then runs month to month. ${OWNERSHIP_LINE}`,
  },
];

const faqLd = {
  "@context": "https://schema.org",
  "@type": "FAQPage",
  mainEntity: [...FAQ, ...CUSTOM_FAQ].map(({ q, a }) => ({ "@type": "Question", name: q, acceptedAnswer: { "@type": "Answer", text: a } })),
};

function FaqList({ items }: { items: FaqItem[] }) {
  return (
    <>
      {items.map(({ q, a, more }) => (
        <details key={q} className="group border-t border-line last:border-b">
          <summary className="flex cursor-pointer list-none items-start justify-between gap-4 py-4 text-base font-semibold tracking-tight marker:content-none [&::-webkit-details-marker]:hidden">
            {q}
            <span aria-hidden className="mt-0.5 flex-none text-fg-3 group-open:rotate-45">
              +
            </span>
          </summary>
          <p className="max-w-[68ch] pb-5 text-sm leading-relaxed text-fg-2">
            {a}
            {more && (
              <>
                {" "}
                <a href={more.href} className="font-medium text-accent-text underline-offset-4 hover:underline">
                  {more.label}
                </a>
              </>
            )}
          </p>
        </details>
      ))}
    </>
  );
}

function Thumbs({ items }: { items: { key: string; src: string; href: string; label: string }[] }) {
  return (
    <ul className="grid grid-cols-4 gap-3">
      {items.map((i) => (
        <li key={i.key}>
          <a href={i.href} aria-label={i.label} className="block overflow-hidden rounded-lg bg-white shadow-[var(--shadow-3)]">
            <span className="relative block aspect-[6/7]">
              <Image src={i.src} alt="" fill sizes="(min-width: 1024px) 160px, 30vw" className="object-cover object-top" />
            </span>
          </a>
        </li>
      ))}
    </ul>
  );
}

export default function PricingPage() {
  return (
    <>
      <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd) }} />
      <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(faqLd) }} />
      <main className="flex-1">
        <section className="container-px pt-10 pb-10 sm:pt-14 lg:pb-12">
          <h1
            className="font-[550] leading-[1.04] tracking-[-0.022em]"
            style={{ fontSize: "clamp(2.1rem, 4.4vw, 3.4rem)" }}
          >
            Websites <span className="text-accent-text">{WEB_FROM}</span>.
          </h1>
          <p className="mt-3 max-w-[48ch] text-lg leading-snug text-fg-2">{VISIBILITY_LINE}.</p>
          <div className="mt-6 flex flex-wrap items-center gap-x-5 gap-y-2">
            <a href={BOOKING_HREF} className="btn btn-primary min-h-[48px]">
              Book a call
            </a>
            <span className="text-sm text-fg-2">{BOOKING_NOTE}</span>
          </div>
        </section>

        {/* WEBSITES */}
        <section aria-label="Websites" style={{ background: SHOP.butter.body, color: INK }}>
          <div className="container-px grid gap-5 py-12 lg:grid-cols-2 lg:gap-6 lg:py-16">
            {[
              {
                t: STARTER,
                thumbs: [
                  ...firstLooks.map((l) => ({ key: l.slug, src: lookPortrait(l), href: l.demoPath, label: `${l.name}: open the live look` })),
                  ...fashionLead.map((b) => ({ key: b.name, src: b.image, href: b.url, label: `${b.name}: open the live site` })),
                ],
              },
              // Custom shows no example build (Macdara, 2026-10-05): its
              // points list sits where the thumbnails would.
              { t: CUSTOM, thumbs: [] },
            ].map(({ t, thumbs }) => (
              <article key={t.name} className="flex flex-col rounded-2xl bg-white p-5 sm:p-7">
                <div className="flex flex-wrap items-baseline justify-between gap-x-4">
                  <h2 className="text-2xl font-semibold tracking-tight">{t.name}</h2>
                  <p className="text-3xl font-semibold tabular-nums tracking-tight sm:text-4xl">{t.price}</p>
                </div>
                <p className="mt-2 text-base leading-snug text-fg-2">{t.tagline}</p>
